        plot("#cz_y", [{ type: "bar", name: "Monsoon rain, % of normal", x: yrs, y: rp, marker: { color: rp.map((p) => LV[lvl(p)[0]]) } }, { x: yrs, y: id, name: "Yield index", mode: "lines+markers", line: { color: "#1d1d1f", width: 2.5 } }], { height: 300, yaxis: { title: "%" }, xaxis: { dtick: 3 } }, "Monsoon rain and yield by year.", { animate: false });
        const cr = corr(rp, id); addRead("#cz_y", `Rain and yield ${cr > 0.3 ? "tend to move together" : cr > 0 ? "move together only weakly" : "do not move together"} here (link ${cr.toFixed(2)}). The driest year, ${worst.year}, had ${worst.rain_pct.toFixed(0)}% of normal rain and a yield index of ${worst.idx.toFixed(0)}.`, "Bars: monsoon rain as % of normal, coloured by drought level. Line: average Kharif yield index (100 = normal).", cr > 0.3 ? "Poor monsoons do cut harvests here, so rain is a real early-warning signal for crops." : "Rain explains only part of the harvest here; irrigation, crop choice and prices matter too, so a dry year is a warning, not a verdict.");
