      const cards = [
        { icon: "spark", color: "#e67700", label: "Yearly AC load", big: cn(hmean(v), 0), unit: " AC load points a year", chip: `Rank ${mine} of ${c.ranking.length} cities`, viz: miniBars(c.ranking.map((r) => r.cdd_per_year), c.ranking.map((r) => (r.location_id === S.city ? "#c92a2a" : "#f1c79a")), {}, c.ranking.map((r) => r.city.slice(0, 3))), text: `Highest: ${c.ranking[0].city} (${fmtn(c.ranking[0].cdd_per_year)}). Red bar is ${L}.`, more: `<h5>Top cities</h5>${mtab(["City", "AC load points per year"], c.ranking.slice(0, 5).map((r) => [r.city, fmtn(r.cdd_per_year)]))}${sowhat("hotter cities run air conditioners for more months, so their grids work harder.")}` },
        { icon: "clock", color: "#c92a2a", label: "Peak-demand month", big: MONTHS[peak.month - 1], unit: "", chip: `${Math.round((100 * t3.reduce((x, y) => x + y[0], 0)) / tot)}% of the load in 3 months`, viz: miniBars(mon, mon.map((x) => LV[lv(x)[0]]), { [mon.indexOf(pk)]: Math.round(pk) + "" }, LET), text: `Electricity use for cooling is concentrated in ${t3.map((x) => MONTHS[x[1]]).join(", ")}.`, more: `<h5>Busiest months</h5>${mtab(["Month", "AC load points"], t3.map(([x, i]) => [MONTHS[i], Math.round(x)]))}${sowhat("this is when power cuts are most likely, so spare supply is needed.")}` },
        { icon: "alert", color: "#e8590c", label: "Heavy-load months", big: cn(hiM, 0), unit: " months of heavy electricity use", chip: hiM >= 5 ? "Long air-conditioning season" : "Short air-conditioning season", viz: `<div class="atiles m">${mon.map((x, i) => `<i style="background:${LV[lv(x)[0]]}" title="${MONTHS[i]}: ${lv(x)[1]}"><em>${LET[i]}</em></i>`).join("")}</div>`, text: `Each tile is a month, coloured by its grid load against ${L}'s own peak.`, more: `<h5>Alert levels</h5>${legend([[LV.green, "Normal load", "under 25% of peak"], [LV.yellow, "Rising load", "25 to 50%"], [LV.orange, "Heavy load, grid strained", "50 to 80%"], [LV.red, "Peak demand, highest outage risk", "80% or more"]])}${sowhat("in Peak months utilities avoid maintenance and ask users to shift heavy use away from the evening.")}` },
        { icon: "trend", color: "#7048e8", label: "Is AC demand rising?", big: cn(Math.abs(ol.slope * 10), 0, ol.slope >= 0 ? "+" : "−"), unit: " AC load points per decade", chip: `Last year ${fmtn(v.at(-1))} · first year ${fmtn(v[0])}`, viz: spark(v, "#7048e8", ol, yrs, 0), text: ol.slope >= 0 ? "Hotter years mean more air conditioners running, so more electricity." : "No rise in air-conditioning need over this period.", more: `<h5>Trend</h5>${mtab(["Measure", "Value"], [["Per decade", sgn(ol.slope * 10, 0)], ["Normal yearly swing", `±${Math.round(hsd(v))}`]])}${sowhat("this comes from weather only, not from meter readings.")}` }];
